import json

_counter = {"id": "1", "value": 0}


def _snapshot():
    return {"id": _counter["id"], "value": _counter["value"]}


def handle(method: str, path: str, body: bytes) -> tuple:
    try:
        p = path or "/"
        if len(p) > 1 and p.endswith("/"):
            p = p.rstrip("/") or "/"
        if not p.startswith("/"):
            p = "/" + p
        m = (method or "").upper()

        if p == "/counter":
            if m == "GET":
                return 200, _snapshot()
            return 405, {"error": "不支援此請求方法"}

        if p == "/counter/increment":
            if m == "POST":
                _counter["value"] += 1
                return 200, _snapshot()
            return 405, {"error": "不支援此請求方法"}

        return 404, {"error": "找不到此路徑"}
    except Exception:
        return 500, {"error": "伺服器發生錯誤，請稍後再試"}

