(function () {
  var countEl = document.getElementById('count');
  var buttonEl = document.getElementById('increment');
  var errorEl = document.getElementById('error');

  function showError(message) {
    errorEl.textContent = message;
    errorEl.hidden = false;
  }

  function clearError() {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }

  function showValue(data) {
    if (data && typeof data.value !== 'undefined') {
      countEl.textContent = String(data.value);
    } else {
      throw new Error('伺服器回應格式不正確');
    }
  }

  async function request(path, options) {
    var res;
    try {
      res = await fetch(path, options);
    } catch (e) {
      throw new Error('無法連線到伺服器，請稍後再試');
    }
    var data = null;
    var text = '';
    try {
      text = await res.text();
      data = text ? JSON.parse(text) : null;
    } catch (e) {
      data = null;
    }
    if (!res.ok) {
      var msg = data && data.error ? data.error : ('請求失敗（狀態碼 ' + res.status + '）');
      throw new Error(msg);
    }
    if (data === null) {
      throw new Error('伺服器回應格式不正確');
    }
    return data;
  }

  async function loadCounter() {
    try {
      var data = await request('api/counter', { method: 'GET' });
      showValue(data);
      clearError();
    } catch (e) {
      countEl.textContent = '–';
      showError('讀取失敗：' + e.message);
    }
  }

  async function increment() {
    buttonEl.disabled = true;
    try {
      var data = await request('api/counter/increment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });
      showValue(data);
      clearError();
    } catch (e) {
      showError('加一失敗：' + e.message);
    } finally {
      buttonEl.disabled = false;
    }
  }

  buttonEl.addEventListener('click', increment);
  document.addEventListener('DOMContentLoaded', loadCounter);
  if (document.readyState !== 'loading') {
    loadCounter();
  }
})();

